/* sklaff_features.h
 *
 * Internal compatibility aliases for historical feature macros.
 *
 * Do not edit this file to configure SklaffKOM.  ./configure generates
 * config.h with the selected features and detected dependencies.
 * New feature switches belong in ./configure, not in this header.
 */

#ifndef SKLAFF_FEATURES_H
#define SKLAFF_FEATURES_H

/* Use the generated configuration even if this header is included directly. */
#ifdef HAVE_CONFIG_H
#include "config.h"
#endif

/* Legacy names kept for existing call sites.  Not independent switches. */
#define ENABLE_OUTBOUND_EMAIL ENABLE_EMAIL
#define ENABLE_ZORK HAVE_FROTZ
#define ENABLE_NETHACK HAVE_NETHACK

#endif /* SKLAFF_FEATURES_H */
